    ex(['05 · Deux retours','05 · Two undos'],['Deux actions récentes sont annulées.','Two recent actions are undone.'],'actions = ["A", "B", "C"]\nfor _ in range(2): print(actions.pop())',['La boucle dépile C puis B.','The loop pops C then B.'])
