  trees: { examples: [
    ex(['01 · Racine','01 · Root'],['Une arborescence de projet commence par une racine.','A project tree starts with a root.'],'arbre = {"valeur":"Projet", "enfants":[]}\nprint(arbre["valeur"])',['La racine est le premier nœud.','The root is the first node.']),
    ex(['02 · Feuilles','02 · Leaves'],['Un dossier feuille ne contient aucun enfant.','A leaf folder has no children.'],'noeud = {"valeur":"README", "enfants":[]}\nprint(noeud["enfants"] == [])',['La liste vide constitue le cas d’arrêt.','The empty list is the stopping case.']),
    ex(['03 · Parcours','03 · Traversal'],['On visite un parent puis ses enfants.','Visit a parent then its children.'],'def visiter(n):\n    print(n["valeur"])\n    for enfant in n["enfants"]: visiter(enfant)',['La même fonction traite chaque sous-arbre.','The same function handles each subtree.']),
    ex(['04 · Hauteur','04 · Height'],['La hauteur compte les niveaux d’une branche.','Height counts branch levels.'],'def hauteur(n):\n    if not n["enfants"]: return 1\n    return 1 + max(hauteur(e) for e in n["enfants"])',['Le cas feuille vaut 1 ; sinon on ajoute un niveau.','A leaf has height 1; otherwise add one level.']),
    ex(['05 · Recherche','05 · Search'],['On cherche une valeur dans une hiérarchie.','Search for a value in a hierarchy.'],'def contient(n, cible):\n    return n["valeur"] == cible or any(contient(e, cible) for e in n["enfants"])',['La recherche s’arrête dès qu’une branche renvoie True.','Search stops when a branch returns True.'])
  ], exercises: [
    task(['01 · Construire','01 · Build'],['Crée une racine avec deux feuilles.','Create a root with two leaves.'],'arbre = {"valeur":"A", "enfants":[{"valeur":"B","enfants":[]},{"valeur":"C","enfants":[]}]}',['Chaque enfant respecte le même modèle.','Each child follows the same model.']),
    task(['02 · Afficher','02 · Display'],['Affiche toutes les valeurs en profondeur.','Display all values depth-first.'],'def afficher(n):\n    print(n["valeur"])\n    for e in n["enfants"]: afficher(e)',['L’appel récursif descend chaque branche.','The recursive call descends every branch.']),
    task(['03 · Compter','03 · Count'],['Compte les nœuds d’un arbre.','Count tree nodes.'],'def compter(n):\n    return 1 + sum(compter(e) for e in n["enfants"])',['1 compte le nœud courant.','1 counts the current node.']),
    task(['04 · Feuille','04 · Leaf'],['Teste si un nœud est une feuille.','Test whether a node is a leaf.'],'def feuille(n): return len(n["enfants"]) == 0',['Aucun enfant signifie feuille.','No child means leaf.']),
    task(['05 · Hauteur','05 · Height'],['Calcule la hauteur récursive.','Calculate recursive height.'],'def h(n):\n    return 1 if not n["enfants"] else 1 + max(h(e) for e in n["enfants"])',['Le cas d’arrêt évite une récursion infinie.','The stopping case prevents infinite recursion.']),
    task(['06 · Recherche','06 · Search'],['Cherche la valeur "Cours".','Search for value “Courses”.'],'trouve = contient(arbre, "Cours")',['or combine le test courant et les enfants.','or combines current test and children.']),
    task(['07 · Niveaux','07 · Levels'],['Affiche avec indentation.','Display with indentation.'],'def afficher(n, niveau=0):\n    print("  " * niveau + n["valeur"])',['niveau évolue à chaque descente.','level changes at each descent.']),
    task(['08 · Feuilles','08 · Leaves'],['Compte seulement les feuilles.','Count only leaves.'],'def feuilles(n):\n    if not n["enfants"]: return 1\n    return sum(feuilles(e) for e in n["enfants"] )',['Le cas feuille renvoie 1.','The leaf case returns 1.']),
    task(['09 · Filtrer','09 · Filter'],['Retourne les nœuds dont le nom commence par C.','Return nodes whose name starts with C.'],'def ok(n): return n["valeur"].startswith("C")',['startswith formalise le critère.','startswith formalizes the criterion.']),
    task(['10 · Arbre vide','10 · Empty tree'],['Protège une fonction contre None.','Protect a function against None.'],'def afficher(n):\n    if n is None: return\n    print(n["valeur"])',['Le test rend le parcours robuste.','The check makes traversal robust.']) ] },
